//! tract-vs-ORT numeric parity for the Laya decision graph.
//!
//! The fixture (`tests/fixtures/laya_decision_golden.json`) is generated by
//! `scripts/gen-laya-golden.py`, which runs the ORIGINAL, un-prepped Laya ONNX
//! under `onnxruntime` and records the raw `logits` / `act_logits` for a set of
//! structurally valid pseudo-random inputs. This test runs the **prepped**
//! graph (see `scripts/prep-laya-onnx.py`) under **tract** and compares.
//!
//! # What this test can and cannot assert
//!
//! The graph is an int8-quantized export, and quantization is a *step*
//! function: any difference in the float activation feeding a
//! `DynamicQuantizeLinear` can flip a discrete code, which the int8 GEMM then
//! amplifies. tract 0.21 and onnxruntime 1.30 differ at the last few ULP on
//! three ops that nothing in the graph can avoid:
//!
//! | op | measured gap | why |
//! |---|---|---|
//! | `Div` | 1 ULP, ~74% of values | tract multiplies by a reciprocal; ORT divides |
//! | `ReduceMean` | 6.5e-9 | different summation order over the hidden axis |
//! | `Erf` | 1.5e-6 | independent transcendental approximations |
//!
//! (`Add`/`Sub`/`Mul`/`Sqrt`/`Exp`/`Sin`/`Cos`/`Abs` are bit-identical, and
//! onnxruntime is self-reproducible across thread counts, so the gap is
//! genuinely engine-vs-engine and not noise.) Those few-ULP gaps land in
//! 3-17% relative error on the outputs -- measured worst 1.65e-1 -- and can
//! flip the winning option when the reference margin is smaller than that.
//!
//! So this test asserts what is *verifiable*, and reports the rest:
//!
//! 1. **Structure**, exactly: logits carry one slot per option, `act_logits`
//!    carries two.
//! 2. **Magnitude band**: outputs agree within `fixture.tolerance`, which is
//!    set to the measured floor with headroom. A real integration bug -- a
//!    transposed weight, a wrong axis, a broken loader -- is an order of
//!    magnitude, not 15%.
//! 3. **The `act` decision** (`argmax` of `act_logits`, act vs escalate):
//!    asserted unconditionally. Its margin is ~2e3 against a ~150 error, so
//!    it is robust.
//! 4. **The option decision** (`argmax` of `logits[:k]`): asserted only when
//!    the reference margin exceeds twice the observed error band, i.e. only
//!    when the reference itself is unambiguous at the precision tract
//!    provides. Always reported.
//!
//! For **bit-exact** agreement with Laya's own Python/onnxruntime reference,
//! run the decision model on onnxruntime itself rather than tract -- see the
//! `ort` executor slot in `src/vision/ort_runtime.rs`, which neuron's ONNX
//! backend is already built to take. Details in
//! `docs/superpowers/specs/2026-09-24-laya-decision.md`.
//!
//! The fixture's `postprocess` group is replayed separately in
//! `src/decision/postprocess.rs`, so it runs under `cargo test --lib` without
//! any model on disk.
//!
//! **Opt-in.** The graph is a ~325 MB quantized checkpoint, which cannot be
//! committed. Set `NEURON_DECISION_MODEL_PATH` to a decision model directory
//! (exactly one prepped `*.onnx`, plus `tokenizer.json`) to enable the test;
//! without it the test reports that it skipped and passes.
//!
//! ```bash
//! python scripts/prep-laya-onnx.py full_int8.onnx ~/.neuron/models/decision/laya/laya.onnx
//! cp tokenizer.json ~/.neuron/models/decision/laya/
//! NEURON_DECISION_MODEL_PATH=~/.neuron/models/decision/laya \
//!     cargo test --test decision_parity -- --nocapture
//! ```

// The whole file is about the tract session, which is itself feature-gated.
#![cfg(feature = "tract")]

use std::path::PathBuf;

/// Mixed absolute/relative tolerance, taken from the fixture.
///
/// `max(|want|, 1.0)` makes this absolute for the small logits and relative
/// for the ~1e3 `act_logits`, which is what one threshold needs to cover both.
/// The value in the fixture is the measured tract-vs-ORT floor (1.65e-1) with
/// headroom -- see the module docs for where that floor comes from.
fn close(got: f64, want: f64, tol: f64) -> bool {
    (got - want).abs() <= tol * want.abs().max(1.0)
}

/// Index of the largest element. Panics on an empty slice rather than
/// silently picking a wrong decision.
fn argmax(v: &[f64]) -> usize {
    assert!(!v.is_empty(), "argmax of an empty slice");
    let mut best = 0;
    for (i, &x) in v.iter().enumerate().skip(1) {
        if x > v[best] {
            best = i;
        }
    }
    best
}

/// Gap between the largest and second-largest element: how decisively the
/// reference picked its winner. Compared against the error band to decide
/// whether a decision mismatch is a bug or float noise.
fn top2_margin(v: &[f64]) -> f64 {
    assert!(v.len() >= 2, "margin needs at least two elements");
    let mut sorted = v.to_vec();
    sorted.sort_by(|a, b| b.partial_cmp(a).unwrap());
    sorted[0] - sorted[1]
}

fn f64_list(v: &serde_json::Value) -> Vec<f64> {
    v.as_array()
        .expect("expected an array")
        .iter()
        .map(|x| x.as_f64().expect("expected a number"))
        .collect()
}

fn i64_list(v: &serde_json::Value) -> Vec<i64> {
    v.as_array()
        .expect("expected an array")
        .iter()
        .map(|x| x.as_i64().expect("expected an integer"))
        .collect()
}

fn bool_list(v: &serde_json::Value) -> Vec<bool> {
    v.as_array()
        .expect("expected an array")
        .iter()
        .map(|x| x.as_bool().expect("expected a boolean"))
        .collect()
}

/// The fixture's `inputs`/`outputs` are stored as `(1, ...)` arrays because
/// that is what `onnxruntime` was handed; the leading batch dim is 1 here.
fn row(v: &serde_json::Value) -> &serde_json::Value {
    let outer = v.as_array().expect("expected an array");
    assert_eq!(outer.len(), 1, "fixture cases are single-row batches");
    &outer[0]
}

/// One fixture case's tensors, shaped the way the runtime's encoder expects.
fn case_item(case: &serde_json::Value) -> neuron_lib::decision::prompt::EncodedQuestion {
    let inputs = &case["inputs"];
    let input_ids = i64_list(row(&inputs["input_ids"]));
    let seq_len = input_ids.len();
    let marker_pos = i64_list(row(&inputs["marker_pos"]));
    let marker_mask = bool_list(row(&inputs["marker_mask"]));
    assert_eq!(marker_pos.len(), marker_mask.len(), "marker widths");
    assert_eq!(
        i64_list(row(&inputs["attention_mask"])).len(),
        seq_len,
        "attention_mask width"
    );
    // `qtype` is `(1,)`, not `(1, 1)`, so `row()` is the wrong accessor.
    let qtype = inputs["qtype"].as_array().expect("qtype is an array")[0]
        .as_i64()
        .expect("qtype is an integer");
    let option_count = case["markers"].as_u64().expect("markers") as usize;
    neuron_lib::decision::prompt::EncodedQuestion {
        attention_mask: vec![1; seq_len],
        input_ids,
        marker_pos,
        marker_mask,
        qtype,
        option_count,
        seq_len,
    }
}

/// The model dir the parity tests need, or `None` when they should skip.
fn model_dir() -> Option<PathBuf> {
    match std::env::var("NEURON_DECISION_MODEL_PATH") {
        Ok(p) if !p.trim().is_empty() => Some(PathBuf::from(p)),
        _ => None,
    }
}

#[test]
fn test_numerics_match_ort_reference() {
    let model_dir = match model_dir() {
        Some(p) => p,
        None => {
            eprintln!(
                "skipping tract-vs-ORT parity: set NEURON_DECISION_MODEL_PATH to a \
                 decision model dir holding the prepped graph (see the module docs)"
            );
            return;
        }
    };

    let fixture: serde_json::Value = serde_json::from_str(include_str!(
        "../tests/fixtures/laya_decision_golden.json"
    ))
    .expect("fixture parses");
    let tol = fixture["tolerance"].as_f64().expect("fixture has a tolerance");
    let numerics = fixture["numerics"].as_array().expect("fixture has numerics");
    assert!(!numerics.is_empty(), "fixture has no numerics cases");

    let rt = neuron_lib::decision::tract_session::TractDecisionRuntime::from_dir(
        "parity",
        &model_dir,
    )
    .unwrap_or_else(|e| panic!("cannot load {} as a decision model: {e}", model_dir.display()));

    // One forward per case: the export hardcodes `act_logits` to `f32[1, 2]`,
    // so the graph is batch-1 and a multi-row batch will not unify.
    let mut worst = 0.0f64;
    let mut reported_only = 0usize;
    for case in numerics {
        let name = case["name"].as_str().unwrap_or("<unnamed>").to_string();
        let outputs = &case["outputs"];

        let item = case_item(case);
        let option_count = item.option_count;

        let batch = neuron_lib::decision::tract_session::collate(&[item], rt.pad_id())
            .unwrap_or_else(|e| panic!("{name}: collate failed: {e}"));
        let (logits, acts) = rt
            .forward(&batch)
            .unwrap_or_else(|e| panic!("{name}: tract forward failed: {e}"));

        // Report every pair before asserting anything: a first-failure panic
        // hides whether the discrepancy is one bad slot or a uniform bias.
        let want_logits = f64_list(row(&outputs["logits"]));
        let want_act = f64_list(row(&outputs["act_logits"]));
        assert_eq!(logits[0].len(), want_logits.len(), "{name}: logits width");
        assert_eq!(acts[0].len(), want_act.len(), "{name}: act_logits width");

        let mut rows: Vec<(String, f64, f64)> = Vec::new();
        for (c, (&got, &want)) in logits[0].iter().zip(want_logits.iter()).enumerate() {
            rows.push((format!("logits[{c}]"), got, want));
        }
        for (c, (&got, &want)) in acts[0].iter().zip(want_act.iter()).enumerate() {
            rows.push((format!("act[{c}]"), got, want));
        }

        let mut local_worst = 0.0f64;
        for (field, got, want) in &rows {
            let rel = (got - want).abs() / want.abs().max(1.0);
            local_worst = local_worst.max(rel);
            worst = worst.max(rel);
            println!(
                "  {name} {field:12} tract={got:>14.8} ort={want:>14.8}  rel={rel:.3e}"
            );
        }
        for (field, got, want) in &rows {
            assert!(
                close(*got, *want, tol),
                "{name}: {field} tract={got} ort={want} (rel {}, tol {tol})",
                (got - want).abs() / want.abs().max(1.0)
            );
        }

        // ---- the decisions themselves ------------------------------------
        // `act` is a two-class head whose margin runs to ~2e3 against an error
        // of ~150, so its winner must always reproduce. The option head is
        // only asserted where the reference is decisive relative to the error
        // measured on this very case: a mismatch inside that band means the
        // reference is ambiguous at tract's precision, not that the
        // integration is wrong.
        let act_err = acts[0]
            .iter()
            .zip(want_act.iter())
            .map(|(g, w)| (g - w).abs())
            .fold(0.0f64, f64::max);
        assert_eq!(
            argmax(&acts[0]),
            argmax(&want_act),
            "{name}: act decision differs (tract {:?} vs ort {:?}, max abs err {act_err:.3e})",
            acts[0],
            want_act
        );

        let n = option_count.min(logits[0].len()).min(want_logits.len());
        let (got_top, want_top) = (&logits[0][..n], &want_logits[..n]);
        let logit_err = got_top
            .iter()
            .zip(want_top.iter())
            .map(|(g, w)| (g - w).abs())
            .fold(0.0f64, f64::max);
        let margin = top2_margin(want_top);
        let decisive = margin > 2.0 * logit_err;
        println!(
            "  {name}: option argmax tract={} ort={} margin={margin:.3e} err={logit_err:.3e} {}",
            argmax(got_top),
            argmax(want_top),
            if decisive {
                "decisive -> asserted"
            } else {
                "inside float band -> reported only"
            }
        );
        if decisive {
            assert_eq!(
                argmax(got_top),
                argmax(want_top),
                "{name}: option decision differs despite a decisive reference margin \
                 {margin:.3e} (error band {logit_err:.3e})"
            );
        } else {
            reported_only += 1;
        }
        println!("  {name}: worst rel {local_worst:.3e}");
    }

    println!(
        "tract-vs-ORT parity: {} case(s), worst relative error {:.3e} (tol {tol}); \
         {reported_only} option decision(s) sat inside the float band and were reported only",
        numerics.len(),
        worst
    );
}

/// A multi-question request against a batch-1 graph must be split into one run
/// per row and reproduce the single-row results exactly.
///
/// "Exactly", not "within tolerance", because the two paths feed the same graph
/// the same tensors: `forward` only has to slice the batch correctly. The
/// comparison is bit-exact on purpose -- an off-by-one in the chunking would
/// show up as a whole wrong row, which a magnitude band would paper over.
#[test]
fn test_multiquestion_batch_matches_single_row_runs() {
    let model_dir = match model_dir() {
        Some(p) => p,
        None => {
            eprintln!("skipping batch-chunking check: set NEURON_DECISION_MODEL_PATH");
            return;
        }
    };
    let fixture: serde_json::Value = serde_json::from_str(include_str!(
        "../tests/fixtures/laya_decision_golden.json"
    ))
    .expect("fixture parses");
    let numerics = fixture["numerics"].as_array().expect("fixture has numerics");
    let rt = neuron_lib::decision::tract_session::TractDecisionRuntime::from_dir(
        "parity",
        &model_dir,
    )
    .unwrap_or_else(|e| panic!("cannot load {} as a decision model: {e}", model_dir.display()));

    let items: Vec<_> = numerics.iter().map(case_item).collect();
    assert!(
        items.len() >= 2,
        "the chunking check needs at least two cases to batch"
    );

    // Reference: one forward per row.
    let mut singles = Vec::with_capacity(items.len());
    for item in &items {
        let b = neuron_lib::decision::tract_session::collate(std::slice::from_ref(item), rt.pad_id())
            .expect("collate a single case");
        singles.push(rt.forward(&b).expect("single-row forward"));
    }

    // One call over every row at once. The graph is grounded at batch 1
    // (`act_logits` is `f32[1, 2]`), so this only succeeds if `forward` splits.
    let batch = neuron_lib::decision::tract_session::collate(&items, rt.pad_id())
        .expect("collate the batch");
    assert_eq!(batch.rows(), items.len());
    let (logits, acts) = rt.forward(&batch).expect("batched forward");
    assert_eq!(logits.len(), items.len(), "one logits row per question");
    assert_eq!(acts.len(), items.len(), "one act pair per question");

    for (i, (s_logits, s_acts)) in singles.iter().enumerate() {
        // Each single-row forward returns exactly one row.
        assert_eq!(s_logits.len(), 1, "case {i}: single-row logits");
        assert_eq!(s_acts.len(), 1, "case {i}: single-row acts");
        let (s_row, s_act) = (&s_logits[0], &s_acts[0]);
        assert_eq!(logits[i].len(), s_row.len(), "case {i}: logits width");
        for (c, (&got, &want)) in logits[i].iter().zip(s_row.iter()).enumerate() {
            assert_eq!(
                got, want,
                "case {i} logits[{c}] differs between the batched and single-row runs"
            );
        }
        for (c, (&got, &want)) in acts[i].iter().zip(s_act.iter()).enumerate() {
            assert_eq!(
                got, want,
                "case {i} act[{c}] differs between the batched and single-row runs"
            );
        }
    }
    println!(
        "batch chunking: {} row(s) reproduced the single-row runs bit-exactly \
         (graph batch extent {:?})",
        items.len(),
        rt.shapes().batch
    );
}
